{"function":"() => { const q=s=>document.querySelector(s); const cs=(e,p)=>p.map(x=>getComputedStyle(e)[x]); const r=e=>{const b=e.getBoundingClientRect();return [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)]};
const out={};
document.querySelectorAll('.rotulo-botao').forEach((e,i)=>out['rot'+i]=[e.textContent, r(e), cs(e,['position','clip','width','height','overflow','color','fontSize'])]);
document.querySelectorAll('.br-tooltip').forEach((e,i)=>out['tip'+i]=[e.id, cs(e,['display','visibility','opacity'])]);
out.caption=[r(q('caption')),cs(q('caption'),['position','clip'])];
out.panelDocs=cs(q('#painel-documentos'),['display']);
out.accContent=cs(q('#acc-duvidas-1'),['display']);
out.msg=[cs(q('#msg-pendencia .content'),['color','backgroundColor']),cs(q('#msg-pendencia'),['backgroundColor'])];
out.stepinfo=[...document.querySelectorAll('.step-info')].map(e=>[e.textContent,cs(e,['color','backgroundColor','fontSize']),r(e)]);
out.stepbtn=[...document.querySelectorAll('.step-progress-btn')].map(e=>[cs(e,['color','backgroundColor']),getComputedStyle(e,'::before').content,getComputedStyle(e,'::before').color,getComputedStyle(e,'::before').backgroundColor, getComputedStyle(e,'::after').content, r(e)]);
return out;}"}

