{"function":"() => { const sel=['.crumb a','.crumb span[aria-current]','.dado-resumo','.detalhe-resumo','.tab-item button','td','th','.accordion .title','#acc-duvidas .title','.header-sign','.rodape-servico .info div','.table-title','.titulo-duvidas','.header-title'];
function lum(c){const m=c.match(/[\d.]+/g).map(Number);const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return [0.2126*f(m[0])+0.7152*f(m[1])+0.0722*f(m[2]), m[3]];}
function bg(e){while(e){const b=getComputedStyle(e).backgroundColor; const m=b.match(/[\d.]+/g).map(Number); if(m.length<4||m[3]>0) return b; e=e.parentElement;} return 'rgb(255,255,255)';}
return sel.map(s=>{const e=document.querySelector(s); if(!e) return [s,null]; const c=getComputedStyle(e); const b=bg(e); const L1=lum(c.color)[0], L2=lum(b)[0]; return [s,c.fontSize,c.fontWeight,c.color,b,((Math.max(L1,L2)+.05)/(Math.min(L1,L2)+.05)).toFixed(2), c.opacity]});}"}

